cat > src/themeStorage.ts <<'EOF'
export const THEME_STORAGE_KEY = 'theme';

export const APP_THEMES = ['light', 'dark'] as const;
export type AppTheme = (typeof APP_THEMES)[number];

export const DEFAULT_APP_THEME: AppTheme = 'light';

export function isAppTheme(value: unknown): value is AppTheme {
  return typeof value === 'string' && (APP_THEMES as readonly string[]).includes(value);
}

/** Reads the persisted theme. Returns `null` if nothing valid is stored or storage is unavailable. */
export function readStoredTheme(): AppTheme | null {
  try {
    const raw = window.localStorage.getItem(THEME_STORAGE_KEY);
    return isAppTheme(raw) ? raw : null;
  } catch {
    // localStorage can throw (disabled storage, privacy mode, SSR without window).
    return null;
  }
}

export function writeStoredTheme(theme: AppTheme): void {
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, theme);
  } catch {
    // Persisting is best-effort: the in-memory theme still applies for this session.
  }
}
EOF

cat > src/useStoredTheme.ts <<'EOF'
import { useCallback, useEffect, useState } from 'react';

import {
  type AppTheme,
  DEFAULT_APP_THEME,
  THEME_STORAGE_KEY,
  isAppTheme,
  readStoredTheme,
  writeStoredTheme,
} from './themeStorage';

/**
 * Theme state backed by localStorage.
 * The initial value is read synchronously so the first render already uses the saved theme.
 * Changes made in another tab are picked up through the `storage` event.
 */
export function useStoredTheme(): [AppTheme, (theme: AppTheme) => void] {
  const [theme, setThemeState] = useState<AppTheme>(() => readStoredTheme() ?? DEFAULT_APP_THEME);

  const setTheme = useCallback((next: AppTheme) => {
    setThemeState(next);
    writeStoredTheme(next);
  }, []);

  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key !== THEME_STORAGE_KEY) return;
      setThemeState(isAppTheme(event.newValue) ? event.newValue : DEFAULT_APP_THEME);
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  return [theme, setTheme];
}
EOF

